#include "PluginEditor.h"
GlassAudioProcessorEditor::GlassAudioProcessorEditor(GlassAudioProcessor&x):AudioProcessorEditor(&x),p(x){setSize(760,390);knob(drive,"DRIVE");knob(character,"2ND HARMONIC");knob(bias,"BIAS");knob(mix,"MIX");knob(output,"OUTPUT");addAndMakeVisible(original);a1=std::make_unique<SA>(p.apvts,"drive",drive);a2=std::make_unique<SA>(p.apvts,"character",character);a3=std::make_unique<SA>(p.apvts,"bias",bias);a4=std::make_unique<SA>(p.apvts,"mix",mix);a5=std::make_unique<SA>(p.apvts,"output",output);a6=std::make_unique<BA>(p.apvts,"original",original);}
void GlassAudioProcessorEditor::knob(juce::Slider&s,const juce::String&name){addAndMakeVisible(s);s.setName(name);s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,80,20);}
void GlassAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(juce::Colour(0xff101318));g.setColour(juce::Colour(0xffffa34d));g.setFont(34);g.drawText("GLASS",20,18,getWidth()-40,45,juce::Justification::centred);g.setFont(13);g.setColour(juce::Colours::white.withAlpha(.75f));for(auto*s:{&drive,&character,&bias,&mix,&output})g.drawText(s->getName(),s->getX(),s->getY()-20,s->getWidth(),18,juce::Justification::centred);}
void GlassAudioProcessorEditor::resized(){int x=28;for(auto*s:{&drive,&character,&bias,&mix,&output}){s->setBounds(x,135,125,150);x+=142;}original.setBounds(300,325,160,28);}
